export const DEFAULT_EXPORT_OPTIONS={width:3840,resolution:'3840',transparent:false,page:'A4',orientation:'landscape',margin:10,pdfMode:'vector'};
export function normalizeExportOptions(raw={}){return {width:Math.max(320,Math.min(8000,Math.round(Number(raw.width)||3840))),resolution:['1920','3840','custom'].includes(raw.resolution)?raw.resolution:raw.width===1920?'1920':raw.width===3840?'3840':'custom',transparent:!!raw.transparent,page:['A4','A3','Letter','sheet'].includes(raw.page)?raw.page:'A4',orientation:raw.orientation==='portrait'?'portrait':'landscape',margin:Math.max(0,Math.min(80,Number.isFinite(Number(raw.margin))?Number(raw.margin):10)),pdfMode:raw.pdfMode==='image'?'image':'vector'};}
export function loadExportOptions(storage=localStorage){try{return normalizeExportOptions({...DEFAULT_EXPORT_OPTIONS,...JSON.parse(storage.getItem('catastrophe-export-options')||'{}')});}catch{return {...DEFAULT_EXPORT_OPTIONS};}}
export function saveExportOptions(options,storage=localStorage){const valid=normalizeExportOptions(options);storage.setItem('catastrophe-export-options',JSON.stringify(valid));return valid;}
